// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Iterator as Iter, IterableIterator } from '@stdlib/types/iter';
import { ArrayLike, Uint64Array as Uint64ArrayInterface } from '@stdlib/types/array';
import { Uint64 } from '@stdlib/types/number';
import ArrayBuffer = require( '@stdlib/array/buffer' );

// Define a union type representing both iterable and non-iterable iterators:
type Iterator = Iter | IterableIterator;

// Value from which a 64-bit unsigned integer can be derived.
type Uint = Uint64 | bigint | number;

/**
* Locale-specific configuration options.
*/
interface LocaleOptions<T = unknown> {
	/**
	* Configuration property.
	*/
	[ key: string | symbol | number ]: T | undefined;
}

/**
* Callback invoked for each element in a source object.
*
* @returns transformed value
*/
type FromNullary<U> = ( this: U ) => Uint;

/**
* Callback invoked for each element in a source object.
*
* @param value - source element
* @returns transformed value
*/
type FromUnary<U> = ( this: U, value: Uint ) => Uint;

/**
* Callback invoked for each element in a source object.
*
* @param value - source element
* @param index - source element index
* @returns transformed value
*/
type FromBinary<U> = ( this: U, value: Uint, index: number ) => Uint;

/**
* Callback invoked for each element in a source object.
*
* @param value - source element
* @param index - source element index
* @returns transformed value
*/
type FromCallback<U> = FromNullary<U> | FromUnary<U> | FromBinary<U>;

/**
* Checks whether an element in an array passes a test.
*
* @returns boolean indicating whether an element in an array passes a test
*/
type NullaryPredicate<U> = ( this: U ) => boolean;

/**
* Checks whether an element in an array passes a test.
*
* @param value - current array element
* @returns boolean indicating whether an element in an array passes a test
*/
type UnaryPredicate<U> = ( this: U, value: Uint64 ) => boolean;

/**
* Checks whether an element in an array passes a test.
*
* @param value - current array element
* @param index - current array element index
* @returns boolean indicating whether an element in an array passes a test
*/
type BinaryPredicate<U> = ( this: U, value: Uint64, index: number ) => boolean;

/**
* Checks whether an element in an array passes a test.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns boolean indicating whether an element in an array passes a test
*/
type TernaryPredicate<U> = ( this: U, value: Uint64, index: number, arr: Uint64Array ) => boolean;

/**
* Checks whether an element in an array passes a test.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns boolean indicating whether an element in an array passes a test
*/
type Predicate<U> = NullaryPredicate<U> | UnaryPredicate<U> | BinaryPredicate<U> | TernaryPredicate<U>;

/**
* Callback invoked for each element in an array.
*
* @returns undefined
*/
type NullaryCallback<U> = ( this: U ) => void;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @returns undefined
*/
type UnaryCallback<U> = ( this: U, value: Uint64 ) => void;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @returns undefined
*/
type BinaryCallback<U> = ( this: U, value: Uint64, index: number ) => void;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns undefined
*/
type TernaryCallback<U> = ( this: U, value: Uint64, index: number, arr: Uint64Array ) => void;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns undefined
*/
type Callback<U> = NullaryCallback<U> | UnaryCallback<U> | BinaryCallback<U> | TernaryCallback<U>;

/**
* Callback invoked for each element in an array.
*
* @returns transformed value
*/
type NullaryMapFcn<U> = ( this: U ) => Uint;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @returns transformed value
*/
type UnaryMapFcn<U> = ( this: U, value: Uint64 ) => Uint;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @returns transformed value
*/
type BinaryMapFcn<U> = ( this: U, value: Uint64, index: number ) => Uint;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns transformed value
*/
type TernaryMapFcn<U> = ( this: U, value: Uint64, index: number, arr: Uint64Array ) => Uint;

/**
* Callback invoked for each element in an array.
*
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns transformed value
*/
type MapFcn<U> = NullaryMapFcn<U> | UnaryMapFcn<U> | BinaryMapFcn<U> | TernaryMapFcn<U>;

/**
* Reducer function invoked for each element in an array.
*
* @returns accumulated result
*/
type NullaryReducer<U> = () => U;

/**
* Reducer function invoked for each element in an array.
*
* @param acc - accumulated result
* @returns accumulated result
*/
type UnaryReducer<U> = ( acc: U ) => U;

/**
* Reducer function invoked for each element in an array.
*
* @param acc - accumulated result
* @param value - current array element
* @returns accumulated result
*/
type BinaryReducer<U> = ( acc: U, value: Uint64 ) => U;

/**
* Reducer function invoked for each element in an array.
*
* @param acc - accumulated result
* @param value - current array element
* @param index - current array element index
* @returns accumulated result
*/
type TernaryReducer<U> = ( acc: U, value: Uint64, index: number ) => U;

/**
* @param acc - accumulated result
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns accumulated result
*/
type QuaternaryReducer<U> = ( acc: U, value: Uint64, index: number, arr: Uint64Array ) => U;

/**
* Reducer function invoked for each element in an array.
*
* @param acc - accumulated result
* @param value - current array element
* @param index - current array element index
* @param arr - array on which the method was called
* @returns accumulated result
*/
type Reducer<U> = NullaryReducer<U> | UnaryReducer<U> | BinaryReducer<U> | TernaryReducer<U> | QuaternaryReducer<U>;

/**
* Comparator function.
*
* @param a - first value for comparison
* @param b - second value for comparison
* @returns number indicating comparison result
*/
type CompareFcn = ( a: Uint64, b: Uint64 ) => number;

/**
* Class for creating a 64-bit unsigned integer array.
*/
declare class Uint64Array implements Uint64ArrayInterface {
	/**
	* 64-bit unsigned integer array constructor.
	*
	* @param arg - length, typed array, array-like object, or buffer
	* @param byteOffset - byte offset (default: 0)
	* @param length - view length
	* @throws ArrayBuffer byte length must be a multiple of `8`
	* @throws if provided only a single argument, must provide a valid argument
	* @throws byte offset must be a nonnegative integer
	* @throws byte offset must be a multiple of `8`
	* @throws view length must be a positive multiple of `8`
	* @throws must provide sufficient memory to accommodate byte offset and view length requirements
	* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws an iterator must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer
	* @returns 64-bit unsigned integer array
	*
	* @example
	* var arr = new Uint64Array();
	* // returns <Uint64Array>
	*
	* var len = arr.length;
	* // returns 0
	*
	* @example
	* var arr = new Uint64Array( 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var arr = new Uint64Array( [ 1 ] );
	* // returns <Uint64Array>[ 1n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new Uint64Array( buf );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Uint64Array( buf, 16 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 64 );
	* var arr = new Uint64Array( buf, 16, 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*/
	constructor( arg?: number | ArrayLike<Uint> | Uint64Array | ArrayBuffer | Iterable<Uint>, byteOffset?: number, length?: number );

	/**
	* Pointer to the underlying data buffer.
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var buf = arr.buffer;
	* // returns <ArrayBuffer>
	*/
	readonly buffer: ArrayBuffer;

	/**
	* Length (in bytes) of the array.
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var byteLength = arr.byteLength;
	* // returns 80
	*/
	readonly byteLength: number;

	/**
	* Offset (in bytes) of the array from the start of its underlying `ArrayBuffer`.
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var byteOffset = arr.byteOffset;
	* // returns 0
	*/
	readonly byteOffset: number;

	/**
	* Size (in bytes) of each array element.
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var nbytes = arr.BYTES_PER_ELEMENT;
	* // returns 8
	*/
	readonly BYTES_PER_ELEMENT: 8;

	/**
	* Number of array elements.
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var len = arr.length;
	* // returns 10
	*/
	readonly length: number;

	/**
	* Returns an array element.
	*
	* @param i - element index
	* @throws index argument must be a nonnegative integer
	* @returns array element
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var z = arr.get( 0 );
	* // returns <Uint64>[ 0n ]
	*
	* arr.set( 1, 0 );
	*
	* var z = arr.get( 0 );
	* // returns <Uint64>[ 1n ]
	*
	* z = arr.get( 100 );
	* // returns undefined
	*/
	get( i: number ): Uint64 | void;

	/**
	* Sets an array element.
	*
	* ## Notes
	*
	* -   When provided a typed array, we must check whether the source array shares the same buffer as the target array and whether the underlying memory overlaps. In particular, we are concerned with the following scenario:
	*
	*     ```text
	*     buf:                ---------------------
	*     src: ---------------------
	*     ```
	*
	*     In the above, as we copy values from `src`, we will overwrite values in the `src` view, resulting in duplicated values copied into the end of `buf`, which is not intended. Hence, to avoid overwriting source values, we must **copy** source values to a temporary array.
	*
	*     In the other overlapping scenario,
	*
	*     ```text
	*     buf: ---------------------
	*     src:                ---------------------
	*     ```
	*
	*     by the time we begin copying into the overlapping region, we are copying from the end of `src`, a non-overlapping region, which means we don't run the risk of copying copied values, rather than the original `src` values as intended.
	*
	*
	* @param value - value(s)
	* @param i - element index at which to start writing values (default: 0)
	* @throws `this` must be a 64-bit unsigned integer array
	* @throws index argument must be a nonnegative integer
	* @throws index argument is out-of-bounds
	* @throws target array lacks sufficient storage to accommodate source values
	* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws first argument must be either a 64-bit unsigned integer, a value which can be converted to a 64-bit unsigned integer, a 64-bit unsigned integer array, or an array-like object containing 64-bit unsigned integers or values which can be converted to 64-bit unsigned integers
	*
	* @example
	* var arr = new Uint64Array( 10 );
	*
	* var z = arr.get( 0 );
	* // returns <Uint64>[ 0n ]
	*
	* arr.set( 1, 0 );
	*
	* z = arr.get( 0 );
	* // returns <Uint64>[ 1n ]
	*/
	set( value: ArrayLike<Uint> | Uint64Array | Uint, i?: number ): void;
}

/**
* Interface defining a 64-bit unsigned integer array constructor which is both "newable" and "callable".
*/
interface Uint64ArrayConstructor {
	/**
	* 64-bit unsigned integer array constructor.
	*
	* @param arg - length, typed array, array-like object, or buffer
	* @param byteOffset - byte offset (default: 0)
	* @param length - view length
	* @throws ArrayBuffer byte length must be a multiple of `8`
	* @throws if provided only a single argument, must provide a valid argument
	* @throws byte offset must be a nonnegative integer
	* @throws byte offset must be a multiple of `8`
	* @throws view length must be a positive multiple of `8`
	* @throws must provide sufficient memory to accommodate byte offset and view length requirements
	* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws an iterator must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer
	* @returns 64-bit unsigned integer array
	*
	* @example
	* var arr = new Uint64Array();
	* // returns <Uint64Array>
	*
	* var len = arr.length;
	* // returns 0
	*
	* @example
	* var arr = new Uint64Array( 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var arr = new Uint64Array( [ 1 ] );
	* // returns <Uint64Array>[ 1n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new Uint64Array( buf );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new Uint64Array( buf, 8 );
	* // returns <Uint64Array>[ 0n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 64 );
	* var arr = new Uint64Array( buf, 16, 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*/
	new( arg?: number | ArrayLike<Uint> | Uint64Array | ArrayBuffer | Iterable<Uint64>, byteOffset?: number, length?: number ): Uint64Array;

	/**
	* 64-bit unsigned integer array constructor.
	*
	* @param arg - length, typed array, array-like object, or buffer
	* @param byteOffset - byte offset (default: 0)
	* @param length - view length
	* @throws ArrayBuffer byte length must be a multiple of `8`
	* @throws if provided only a single argument, must provide a valid argument
	* @throws byte offset must be a nonnegative integer
	* @throws byte offset must be a multiple of `8`
	* @throws view length must be a positive multiple of `8`
	* @throws must provide sufficient memory to accommodate byte offset and view length requirements
	* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws an iterator must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer
	* @returns 64-bit unsigned integer array
	*
	* @example
	* var arr = new Uint64Array();
	* // returns <Uint64Array>
	*
	* var len = arr.length;
	* // returns 0
	*
	* @example
	* var arr = new Uint64Array( 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var arr = new Uint64Array( [ 1 ] );
	* // returns <Uint64Array>[ 1n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new Uint64Array( buf );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new Uint64Array( buf, 8 );
	* // returns <Uint64Array>[ 0n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 64 );
	* var arr = new Uint64Array( buf, 16, 2 );
	* // returns <Uint64Array>[ 0n, 0n ]
	*
	* var len = arr.length;
	* // returns 2
	*/
	( arg?: number | ArrayLike<Uint> | Uint64Array | ArrayBuffer | Iterable<Uint>, byteOffset?: number, length?: number ): Uint64Array;

	/**
	* Constructor name.
	*
	* @example
	* var str = Uint64Array.name;
	* // returns 'Uint64Array'
	*/
	readonly name: 'Uint64Array';

	/**
	* Size (in bytes) of each array element.
	*
	* @example
	* var nbytes = Uint64Array.BYTES_PER_ELEMENT;
	* // returns 8
	*/
	readonly BYTES_PER_ELEMENT: 8;

	/**
	* Creates a new 64-bit unsigned integer array from an array-like object or an iterable.
	*
	* @param src - array-like object or iterable
	* @param clbk - callback to invoke for each source element
	* @param thisArg - context
	* @throws `this` context must be a constructor
	* @throws `this` must be a 64-bit unsigned integer array
	* @throws First argument must be an array-like object or an iterable
	* @throws Second argument must be a function
	* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws an iterator must return either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
	* @throws when provided an iterator, a callback must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer
	* @returns 64-bit unsigned integer array
	*
	* @example
	* var arr = Uint64Array.from( [ 1 ] );
	* // returns <Uint64Array>[ 1n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var Uint64 = require( '@stdlib/number/uint64/ctor' );
	*
	* var arr = Uint64Array.from( [ new Uint64( 1 ) ] );
	* // returns <Uint64Array>[ 1n ]
	*
	* var len = arr.length;
	* // returns 1
	*
	* @example
	* var Uint64 = require( '@stdlib/number/uint64/ctor' );
	* var add = require( '@stdlib/number/uint64/base/add' );
	*
	* function clbk( v ) {
	*     return add( v, v );
	* }
	*
	* var arr = Uint64Array.from( [ 1, 2 ], clbk );
	* // returns <Uint64Array>[ 2n, 4n ]
	*
	* var len = arr.length;
	* // returns 2
	*/
	from<U = unknown>( src: ArrayLike<Uint> | Uint64Array | Iterable<Uint>, clbk?: FromCallback<U>, thisArg?: ThisParameterType<FromCallback<U>> ): Uint64Array;

	/**
	* Creates a new 64-bit unsigned integer array from a variable number of arguments.
	*
	* @param elements - array elements
	* @returns 64-bit unsigned integer array
	*
	* @example
	* var arr = Uint64Array.of( 1, 2, 3, 4 );
	* // returns <Uint64Array>[ 1n, 2n, 3n, 4n ]
	*
	* var len = arr.length;
	* // returns 4
	*/
	of( ...elements: Array<Uint> ): Uint64Array;
}

/**
* 64-bit unsigned integer array constructor.
*
* @param arg - length, typed array, array-like object, or buffer
* @param byteOffset - byte offset (default: 0)
* @param length - view length
* @throws ArrayBuffer byte length must be a multiple of `8`
* @throws if provided only a single argument, must provide a valid argument
* @throws byte offset must be a nonnegative integer
* @throws byte offset must be a multiple of `8`
* @throws view length must be a positive multiple of `8`
* @throws must provide sufficient memory to accommodate byte offset and view length requirements
* @throws an array element must be either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer
* @throws an iterator must return either a 64-bit unsigned integer or a value which can be converted to 64-bit unsigned integer
* @returns 64-bit unsigned integer array
*
* @example
* var arr = new Uint64Array();
* // returns <Uint64Array>
*
* var len = arr.length;
* // returns 0
*
* @example
* var arr = new Uint64Array( 2 );
* // returns <Uint64Array>[ 0n, 0n ]
*
* var len = arr.length;
* // returns 2
*
* @example
* var arr = new Uint64Array( [ 1 ] );
* // returns <Uint64Array>[ 1n ]
*
* var len = arr.length;
* // returns 1
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 16 );
* var arr = new Uint64Array( buf );
* // returns <Uint64Array>[ 0n, 0n ]
*
* var len = arr.length;
* // returns 2
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 16 );
* var arr = new Uint64Array( buf, 8 );
* // returns <Uint64Array>[ 0n ]
*
* var len = arr.length;
* // returns 1
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 64 );
* var arr = new Uint64Array( buf, 16, 2 );
* // returns <Uint64Array>[ 0n, 0n ]
*
* var len = arr.length;
* // returns 2
*/
declare var ctor: Uint64ArrayConstructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Uint64Array
